// Competition build_castles prices every structure currently owned by the
// builder. Types 3 and 4 are castles and generals respectively.
static int live_castle_cost(const Observation&o,int site,int w){int cost=35;if(site<0||site>=(int)o.type.size()||w<=0)return cost;for(int s=0;s<(int)o.type.size();++s)if(o.owner[s]==1&&(o.type[s]==3||o.type[s]==4)){int d=std::abs(site/w-s/w)+std::abs(site%w-s%w);cost+=std::max(0,14-2*d);}return cost;}
