 EdgePickerState picker_;bool picker_enabled_=true;int edge_picker_threshold_=16,picker_wait_=0;double edge_picker_min_efficiency_=2.0;long picker_starts_=0,picker_completions_=0,picker_moves_=0,picker_aborts_=0,picker_units_delivered_=0,picker_blocked_ticks_=0,picker_lost_aborts_=0,picker_depleted_aborts_=0,picker_source_guard_rejects_=0,picker_critical_preempt_moves_=0,picker_start_mass_rejects_=0,picker_start_efficiency_rejects_=0,picker_planned_mass_sum_=0,picker_planned_moves_sum_=0;
