 void init(const Observation&o){g_={h_,w_,std::vector<char>(n_),{}, {}};for(int x=0;x<n_;++x){g_.passable[x]=o.type[x]!=2&&o.type[x]!=5;if(o.type[x]==4&&o.owner[x]==1)general_=x;}g_.build();castles_=plan_castles(g_,general_);belief_.initialise(g_,general_);last_owner_=o.owner;last_army_=o.army;packet_at_.assign(n_,0);owned_castle_history_.assign(n_,0);for(int x=0;x<n_;++x)if(o.owner[x]==1&&o.type[x]==3)owned_castle_history_[x]=1;if(const char*e=std::getenv("V35_DOOMGUARD_ENABLED"))doomguard_enabled_=std::atoi(e)!=0;if(const char*e=std::getenv("V35_PICKER_ENABLED"))picker_enabled_=std::strcmp(e,"0")!=0;if(const char*e=std::getenv("V35_EDGE_PICKER_THRESHOLD")){int v=std::atoi(e);if(v>=0&&v<=100)edge_picker_threshold_=v;}if(const char*e=std::getenv("V36_EDGE_PICKER_MIN_EFFICIENCY")){double v=std::atof(e);if(v>=0.0&&v<=20.0)edge_picker_min_efficiency_=v;}if(const char*e=std::getenv("V35_MUSTER_THRESHOLD")){int v=std::atoi(e);if(v>=4&&v<=50)muster_threshold_=v;}std::fprintf(stderr,"[v35_plan] c1=%d cost1=%d c2=%d cost2=%d total=%d\n",castles_.c1,castles_.cost1,castles_.c2,castles_.cost2,castles_.total);}
 int reserve(const Observation&o,int x)const{if(x==general_)return std::max(5,o.opp_army/12);for(int d=0;d<4;++d){int y=g_.neighbor(x,d);if(y>=0&&o.owner[y]==2)return std::max(2,o.army[y]+1);}return 1;}
 std::vector<std::pair<int,int>> feeders(const Observation&o,int target)const{std::vector<std::pair<int,int>>f;if(target<0)return f;for(int x=0;x<n_;++x)if(source(o,x)&&g_.dist[x][target]<INF){int surplus=std::max(0,o.army[x]-reserve(o,x));if(surplus)f.push_back({surplus,g_.dist[x][target]});}return f;}
 bool enemy_adjacent_ours(const Observation&o,int x)const{for(int d=0;d<4;++d){int y=g_.neighbor(x,d);if(y>=0&&o.owner[y]==1)return true;}return false;}
 bool moved_enemy(const Observation&o,int x)const{if(o.owner[x]!=2||o.army[x]<=1)return false;if(last_owner_[x]==2&&last_army_[x]!=o.army[x])return true;for(int d=0;d<4;++d){int y=g_.neighbor(x,d);if(y>=0&&last_owner_[y]==2&&last_army_[y]>1&&last_army_[y]>=o.army[x]-2&&last_army_[x]<=1)return true;}return false;}
