 bool safe_step(const Observation&o,int x,int y)const{if(y<0||!g_.passable[y])return false;if(o.owner[y]==2)return safe_attack(o,x,y);for(int d=0;d<4;++d){int z=g_.neighbor(y,d);if(z>=0&&o.owner[z]==2&&o.army[z]>=o.army[x]-1)return false;}return true;}
 int tactical_next(const Observation&o,int x,int target)const{int best=-1,bd=INF;for(int d=0;d<4;++d){int y=g_.neighbor(x,d);if(safe_step(o,x,y)&&g_.dist[y][target]<bd)best=y,bd=g_.dist[y][target];}return best;}
 bool picker_transit_safe(const Observation&o,int x)const{if(x<0||x>=n_||o.owner[x]!=1||!g_.passable[x])return false;if(x==general_)return true;if(o.type[x]==3||x==castles_.c1||x==castles_.c2)return false;for(int d=0;d<4;++d){int z=g_.neighbor(x,d);if(z>=0&&o.owner[z]==2)return false;}return true;}
 bool picker_route_safe(const Observation&o,int x,int stack)const{if(x<0||x>=n_||o.owner[x]!=1||!g_.passable[x])return false;if(x==general_)return true;for(int d=0;d<4;++d){int z=g_.neighbor(x,d);if(z>=0&&o.owner[z]==2&&o.army[z]>=std::max(1,stack-1))return false;}return true;}
 bool wall_contains(int x,int wall)const{int r=x/w_,col=x%w_;return wall==0?r==0:wall==1?col==w_-1:wall==2?r==h_-1:col==0;}
 int wall_coord(int x,int wall)const{return (wall==0||wall==2)?x%w_:x/w_;}
 int wall_cell_at(int wall,int coord)const{if(wall==0)return coord>=0&&coord<w_?coord:-1;if(wall==2)return coord>=0&&coord<w_?(h_-1)*w_+coord:-1;if(wall==1)return coord>=0&&coord<h_?coord*w_+w_-1:-1;return coord>=0&&coord<h_?coord*w_:-1;}
 bool wall_irrelevant(int wall,int sink)const{if(general_<0)return false;if(sink<0)return true;int gr=general_/w_,gc=general_%w_,sr=sink/w_,sc=sink%w_;if(wall==0)return sr>=gr-1;if(wall==2)return sr<=gr+1;if(wall==3)return sc>=gc-1;return sc<=gc+1;}
