 int owned_next_to_general(const Observation&o,int from)const{if(from<0||general_<0||from==general_)return -1;int stack=std::max(2,o.army[from]);auto search=[&](bool avoid_structures){std::vector<int>d(n_,-1);std::queue<int>q;d[general_]=0;q.push(general_);while(!q.empty()){int x=q.front();q.pop();for(int k=0;k<4;++k){int y=g_.neighbor(x,k);if(y<0||d[y]>=0||o.owner[y]!=1||!g_.passable[y])continue;if(y!=from&&y!=general_){if(avoid_structures&&(o.type[y]==3||y==castles_.c1||y==castles_.c2))continue;if(!picker_route_safe(o,y,stack))continue;}d[y]=d[x]+1;q.push(y);}}int best=-1,bd=INF;for(int k=0;k<4;++k){int y=g_.neighbor(from,k);if(y>=0&&d[y]>=0&&picker_route_safe(o,y,stack)&&d[y]<bd){best=y;bd=d[y];}}return best;};int y=search(true);return y>=0?y:search(false);}
